const BODY_MAX = 180;
/** Cuts on code points (never inside an emoji or a surrogate pair), with an ellipsis. */
export function cutText(s: string, max = BODY_MAX): string {
  const cps = Array.from(s.replace(/\s+/g, " ").trim());
  return cps.length <= max ? cps.join("") : cps.slice(0, max - 1).join("").trimEnd() + "…";
}
