export type NotificationKind = keyof typeof NOTIFICATION_KINDS;
export type NotificationData<K extends NotificationKind> = z.input<(typeof NOTIFICATION_KINDS)[K]["data"]>;
export const NOTIFICATION_KIND_NAMES = Object.keys(NOTIFICATION_KINDS) as NotificationKind[];
export const isNotificationKind = (k: unknown): k is NotificationKind => typeof k === "string" && Object.prototype.hasOwnProperty.call(NOTIFICATION_KINDS, k);

/** An in-app path: one leading slash, not "//", no backslash, whitespace or control characters. */
const IN_APP = /^\/(?!\/)[^\\\s\p{Cc}]*$/u;
export const FALLBACK_HREF = "/notifications";
export const safeHref = (href: unknown): string => (typeof href === "string" && href.length <= 300 && IN_APP.test(href) ? href : FALLBACK_HREF);

export interface DescribedNotification extends NotificationText {
  href: string;
  group: NotificationGroup;
}

const UNKNOWN: DescribedNotification = { title: "Phriend", body: "Open your notifications.", href: FALLBACK_HREF, group: "phriend" };

/**
 * The copy and link of a notification. Unknown kinds (a newer server) and data that does not match fall back to a
 * neutral row that opens the bell; it never throws.
 */
export function describeNotification(kind: string, data: unknown, side: NotificationSide): DescribedNotification {
  if (!isNotificationKind(kind)) return UNKNOWN;
  const def = NOTIFICATION_KINDS[kind] as unknown as KindDef<z.ZodType>;
  const parsed = def.data.safeParse(data);
  if (!parsed.success) return { ...UNKNOWN, group: def.group };
  const t = def.text(parsed.data);
  return { title: cutText(t.title, 80), body: cutText(t.body), href: safeHref(def.href(parsed.data, side)), group: def.group };
}

